            int i = c / 2, j = c / 2 + c % 2;
            while (i >= 0 && j < n && s.charAt(i) == s.charAt(j)) { i--; j++; }
            if (j - i - 1 > bestLen) { bestLen = j - i - 1; bestI = i + 1; }
        }
        return s.substring(bestI, bestI + bestLen);
    }
}

